import re
import sys

KEYWORDS = {
    'and', 'break', 'do', 'else', 'elseif', 'end', 'false', 'for',
    'function', 'goto', 'if', 'in', 'local', 'nil', 'not', 'or',
    'repeat', 'return', 'then', 'true', 'until', 'while'
}

class Token:
    def __init__(self, type_, value, line, col):
        self.type = type_
        self.value = value
        self.line = line
        self.col = col

    def __repr__(self):
        return f"Token({self.type}, {repr(self.value)}, L{self.line}:{self.col})"

class LexerError(Exception):
    def __init__(self, msg, line, col):
        super().__init__(f"chunk:{line}: {msg}")
        self.msg = msg
        self.line = line
        self.col = col

class Lexer:
    def __init__(self, text, chunkname="chunk"):
        self.text = text
        self.chunkname = chunkname
        self.pos = 0
        self.line = 1
        self.col = 1
        self.len = len(text)

    def error(self, msg):
        raise LexerError(msg, self.line, self.col)

    def peek(self, n=0):
        p = self.pos + n
        if p < self.len:
            return self.text[p]
        return ''

    def advance(self, n=1):
        for _ in range(n):
            if self.pos < self.len:
                ch = self.text[self.pos]
                self.pos += 1
                if ch == '\n':
                    self.line += 1
                    self.col = 1
                else:
                    self.col += 1

    def skip_whitespace_and_comments(self):
        while self.pos < self.len:
            ch = self.text[self.pos]
            if ch in ' \t\r\n\f\v':
                self.advance()
            elif ch == '-' and self.peek(1) == '-':
                # Comment
                if self.peek(2) == '[':
                    # Check for long comment --[=[ ... ]=]
                    sep_len = 0
                    p = self.pos + 3
                    while p < self.len and self.text[p] == '=':
                        sep_len += 1
                        p += 1
                    if p < self.len and self.text[p] == '[':
                        # Long comment!
                        close_str = ']' + '=' * sep_len + ']'
                        end_pos = self.text.find(close_str, p + 1)
                        if end_pos == -1:
                            self.error("unfinished long comment")
                        skip_count = (end_pos + len(close_str)) - self.pos
                        self.advance(skip_count)
                        continue
                # Single line comment
                while self.pos < self.len and self.text[self.pos] != '\n':
                    self.advance()
            else:
                break

    def read_long_string(self):
        # Assumes pos is at '['
        start_line, start_col = self.line, self.col
        self.advance() # skip '['
        sep_len = 0
        while self.peek() == '=':
            sep_len += 1
            self.advance()
        if self.peek() != '[':
            self.error("invalid long string delimiter")
        self.advance() # skip '['
        if self.peek() == '\n':
            self.advance() # Discard leading newline

        close_str = ']' + '=' * sep_len + ']'
        end_pos = self.text.find(close_str, self.pos)
        if end_pos == -1:
            raise LexerError("unfinished long string", start_line, start_col)

        val = self.text[self.pos:end_pos]
        self.advance(end_pos - self.pos + len(close_str))
        return val

    def read_string(self, quote):
        start_line, start_col = self.line, self.col
        self.advance() # skip open quote
        res = []
        while self.pos < self.len:
            ch = self.text[self.pos]
            if ch == quote:
                self.advance()
                return ''.join(res)
            elif ch == '\n' or ch == '\r':
                raise LexerError("unfinished string", start_line, start_col)
            elif ch == '\\':
                self.advance()
                if self.pos >= self.len:
                    raise LexerError("unfinished string", start_line, start_col)
                nxt = self.text[self.pos]
                if nxt == 'a': res.append('\x07')
                elif nxt == 'b': res.append('\x08')
                elif nxt == 'f': res.append('\x0c')
                elif nxt == 'n': res.append('\n')
                elif nxt == 'r': res.append('\r')
                elif nxt == 't': res.append('\t')
                elif nxt == 'v': res.append('\x0b')
                elif nxt == '\\': res.append('\\')
                elif nxt == '"': res.append('"')
                elif nxt == "'": res.append("'")
                elif nxt == '\n': res.append('\n')
                elif nxt == 'z':
                    self.advance()
                    while self.pos < self.len and self.text[self.pos] in ' \t\r\n\f\v':
                        self.advance()
                    continue
                elif nxt == 'x':
                    # Hex byte \xXX
                    hex_str = self.text[self.pos+1:self.pos+3]
                    if len(hex_str) == 2 and all(c in '0123456789abcdefABCDEF' for c in hex_str):
                        res.append(chr(int(hex_str, 16)))
                        self.advance(2) # skip 'x' and 2 hex digits
                    else:
                        raise LexerError("hexadecimal digit expected", self.line, self.col)
                elif nxt == 'u':
                    # UTF-8 \u{XXX}
                    if self.peek(1) == '{':
                        p = self.text.find('}', self.pos + 2)
                        if p != -1:
                            hex_str = self.text[self.pos+2:p]
                            try:
                                code = int(hex_str, 16)
                                res.append(chr(code))
                                skip_n = (p - self.pos)
                                self.advance(skip_n)
                            except ValueError:
                                raise LexerError("UTF-8 value too large", self.line, self.col)
                        else:
                            raise LexerError("missing '}' in UTF-8 escape", self.line, self.col)
                    else:
                        raise LexerError("missing '{' in UTF-8 escape", self.line, self.col)
                elif nxt.isdigit():
                    # Decimal byte \ddd (1-3 digits)
                    num_str = ''
                    for i in range(3):
                        if self.pos < self.len and self.text[self.pos].isdigit():
                            num_str += self.text[self.pos]
                            self.advance()
                        else:
                            break
                    val = int(num_str)
                    if val > 255:
                        raise LexerError("decimal escape too large", self.line, self.col)
                    res.append(chr(val))
                    continue # already advanced
                else:
                    res.append(nxt)
                self.advance()
            else:
                res.append(ch)
                self.advance()
        raise LexerError("unfinished string", start_line, start_col)

    def read_number(self):
        start_pos = self.pos
        # Hex number
        if self.peek() == '0' and self.peek(1) in 'xX':
            self.advance(2)
            has_dot = False
            has_p = False
            while self.pos < self.len:
                ch = self.text[self.pos]
                if ch in '0123456789abcdefABCDEF':
                    self.advance()
                elif ch == '.' and not has_dot and not has_p:
                    has_dot = True
                    self.advance()
                elif ch in 'pP' and not has_p:
                    has_p = True
                    self.advance()
                    if self.peek() in '+-':
                        self.advance()
                else:
                    break
            num_str = self.text[start_pos:self.pos]
            if has_dot or has_p:
                try:
                    val = float.fromhex(num_str)
                    return val
                except ValueError:
                    self.error(f"malformed number '{num_str}'")
            else:
                try:
                    val = int(num_str, 16)
                    # Convert to signed 64-bit int if needed
                    if val >= (1 << 63):
                        val = val - (1 << 64)
                    return val
                except ValueError:
                    self.error(f"malformed number '{num_str}'")

        # Decimal number
        has_dot = False
        has_e = False
        while self.pos < self.len:
            ch = self.text[self.pos]
            if ch.isdigit():
                self.advance()
            elif ch == '.' and not has_dot and not has_e:
                has_dot = True
                self.advance()
            elif ch in 'eE' and not has_e:
                has_e = True
                self.advance()
                if self.peek() in '+-':
                    self.advance()
            else:
                break
        num_str = self.text[start_pos:self.pos]
        if has_dot or has_e:
            try:
                return float(num_str)
            except ValueError:
                self.error(f"malformed number '{num_str}'")
        else:
            try:
                val = int(num_str)
                return val
            except ValueError:
                self.error(f"malformed number '{num_str}'")

    def next_token(self):
        self.skip_whitespace_and_comments()
        if self.pos >= self.len:
            return Token('TK_EOF', None, self.line, self.col)

        line, col = self.line, self.col
        ch = self.text[self.pos]

        # Identifier or Keyword
        if ch.isalpha() or ch == '_':
            start = self.pos
            while self.pos < self.len and (self.text[self.pos].isalnum() or self.text[self.pos] == '_'):
                self.advance()
            val = self.text[start:self.pos]
            if val in KEYWORDS:
                return Token('TK_KEYWORD', val, line, col)
            return Token('TK_NAME', val, line, col)

        # Number
        if ch.isdigit() or (ch == '.' and self.peek(1).isdigit()):
            val = self.read_number()
            return Token('TK_NUMBER', val, line, col)

        # String
        if ch in '"\'':
            val = self.read_string(ch)
            return Token('TK_STRING', val, line, col)

        # Long String or '['
        if ch == '[':
            if self.peek(1) in '[=':
                val = self.read_long_string()
                return Token('TK_STRING', val, line, col)

        # Multi-char operators
        if ch == '.' and self.peek(1) == '.' and self.peek(2) == '.':
            self.advance(3)
            return Token('TK_OP', '...', line, col)
        if ch == '.' and self.peek(1) == '.':
            self.advance(2)
            return Token('TK_OP', '..', line, col)
        if ch == '=' and self.peek(1) == '=':
            self.advance(2)
            return Token('TK_OP', '==', line, col)
        if ch == '~' and self.peek(1) == '=':
            self.advance(2)
            return Token('TK_OP', '~=', line, col)
        if ch == '<' and self.peek(1) == '=':
            self.advance(2)
            return Token('TK_OP', '<=', line, col)
        if ch == '>' and self.peek(1) == '=':
            self.advance(2)
            return Token('TK_OP', '>=', line, col)
        if ch == '/' and self.peek(1) == '/':
            self.advance(2)
            return Token('TK_OP', '//', line, col)
        if ch == '<' and self.peek(1) == '<':
            self.advance(2)
            return Token('TK_OP', '<<', line, col)
        if ch == '>' and self.peek(1) == '>':
            self.advance(2)
            return Token('TK_OP', '>>', line, col)
        if ch == ':' and self.peek(1) == ':':
            self.advance(2)
            return Token('TK_OP', '::', line, col)

        # Single-char operators/punctuation
        self.advance()
        return Token('TK_CHAR', ch, line, col)
