            elif t.value == 'while': return self.parse_while()
            elif t.value == 'repeat': return self.parse_repeat()
            elif t.value == 'for': return self.parse_for()
            elif t.value == 'do': return self.parse_do()
            elif t.value == 'local': return self.parse_local()
            elif t.value == 'function': return self.parse_function_stat()
            elif t.value == 'return': return self.parse_return()
            elif t.value == 'break':
                self.advance()
                return BreakStat()
            elif t.value == 'goto':
                self.advance()
                lbl = self.expect('TK_NAME')
                return GotoStat(lbl)

        if t.type == 'TK_OP' and t.value == '::':
            self.advance()
            lbl = self.expect('TK_NAME')
            self.expect('TK_OP', '::')
            return LabelStat(lbl)

        # Assignment or FuncCallStat
        expr = self.parse_primary_expr()
        if isinstance(expr, (FuncCall, MethodCall)):
            return FuncCallStat(expr)

        # Must be assignment
        targets = [expr]
        while self.match('TK_CHAR', ','):
            targets.append(self.parse_primary_expr())
        self.expect('TK_CHAR', '=')
        exprs = self.parse_explist()
        return AssignStat(targets, exprs)

    def parse_if(self):
        self.advance() # skip 'if'
        cond = self.parse_expr()
        self.expect('TK_KEYWORD', 'then')
        block = self.parse_block()
        branches = [(cond, block)]
        else_block = None
        while self.token.type == 'TK_KEYWORD' and self.token.value == 'elseif':
            self.advance()
            c = self.parse_expr()
            self.expect('TK_KEYWORD', 'then')
            b = self.parse_block()
            branches.append((c, b))
        if self.token.type == 'TK_KEYWORD' and self.token.value == 'else':
            self.advance()
            else_block = self.parse_block()
        self.expect('TK_KEYWORD', 'end')
        return IfStat(branches, else_block)

    def parse_while(self):
        self.advance()
        cond = self.parse_expr()
        self.expect('TK_KEYWORD', 'do')
        block = self.parse_block()
        self.expect('TK_KEYWORD', 'end')
        return WhileStat(cond, block)

    def parse_repeat(self):
        self.advance()
        block = self.parse_block()
        self.expect('TK_KEYWORD', 'until')
        cond = self.parse_expr()
        return RepeatStat(block, cond)

    def parse_for(self):
        self.advance() # skip 'for'
        name = self.expect('TK_NAME')
        if self.match('TK_CHAR', '='):
            # Numeric for
            start = self.parse_expr()
            self.expect('TK_CHAR', ',')
            stop = self.parse_expr()
            step = NumberLiteral(1)
            if self.match('TK_CHAR', ','):
                step = self.parse_expr()
            self.expect('TK_KEYWORD', 'do')
            block = self.parse_block()
            self.expect('TK_KEYWORD', 'end')
            return NumForStat(name, start, stop, step, block)
        else:
            # Generic for
            var_names = [name]
            while self.match('TK_CHAR', ','):
                var_names.append(self.expect('TK_NAME'))
            self.expect('TK_KEYWORD', 'in')
            explist = self.parse_explist()
            self.expect('TK_KEYWORD', 'do')
            block = self.parse_block()
            self.expect('TK_KEYWORD', 'end')
            return GenericForStat(var_names, explist, block)

    def parse_do(self):
        self.advance()
        block = self.parse_block()
        self.expect('TK_KEYWORD', 'end')
        return DoStat(block)

    def parse_local(self):
        self.advance() # skip 'local'
        if self.token.type == 'TK_KEYWORD' and self.token.value == 'function':
            self.advance()
            name = self.expect('TK_NAME')
            params, is_vararg, body = self.parse_func_body()
            return LocalAssignStat([name], [FunctionDef(params, is_vararg, body)])

        names = []
        attribs = {}
        while True:
            name = self.expect('TK_NAME')
            names.append(name)
            if self.match('TK_CHAR', '<'):
                attr = self.expect('TK_NAME')
                self.expect('TK_CHAR', '>')
                attribs[name] = f"<{attr}>"
            if not self.match('TK_CHAR', ','):
                break
        exprs = []
        if self.match('TK_CHAR', '='):
            exprs = self.parse_explist()
        return LocalAssignStat(names, exprs, attribs)

    def parse_function_stat(self):
        self.advance() # skip 'function'
        obj = VarRef(self.expect('TK_NAME'))
        while self.match('TK_CHAR', '.'):
            field = self.expect('TK_NAME')
            obj = FieldAccess(obj, field)
        is_method = False
        if self.match('TK_CHAR', ':'):
            method = self.expect('TK_NAME')
            is_method = True
        params, is_vararg, body = self.parse_func_body()
        if is_method:
            params = ['self'] + params
            target = FieldAccess(obj, method)
        else:
            target = obj
        return AssignStat([target], [FunctionDef(params, is_vararg, body)])

    def parse_func_body(self):
        self.expect('TK_CHAR', '(')
        params = []
        is_vararg = False
        if not self.match('TK_CHAR', ')'):
            while True:
                if self.match('TK_OP', '...'):
                    is_vararg = True
                    break
                params.append(self.expect('TK_NAME'))
                if not self.match('TK_CHAR', ','):
                    break
            if not is_vararg:
                self.expect('TK_CHAR', ')')
            else:
                self.expect('TK_CHAR', ')')
        body = self.parse_block()
        self.expect('TK_KEYWORD', 'end')
        return params, is_vararg, body

    def parse_return(self):
        self.advance()
        exprs = []
        if self.token.type != 'TK_EOF' and not (self.token.type == 'TK_KEYWORD' and self.token.value in ('end', 'else', 'elseif', 'until')) and self.token.value != ';':
            exprs = self.parse_explist()
        return ReturnStat(exprs)

    def parse_explist(self):
        exprs = [self.parse_expr()]
        while self.match('TK_CHAR', ','):
            exprs.append(self.parse_expr())
        return exprs

    def parse_expr(self, min_prec=0):
        # Prefix / Unary
        if self.token.type == 'TK_KEYWORD' and self.token.value in UNARY_OPS:
            op = self.token.value
            self.advance()
            operand = self.parse_expr(11) # Unary precedence
            left = UnaryOp(op, operand)
        elif self.token.type == 'TK_CHAR' and self.token.value in ('-', '#', '~'):
            op = self.token.value
            self.advance()
            operand = self.parse_expr(11)
            left = UnaryOp(op, operand)
        else:
            left = self.parse_primary_expr()

        # Infix operators
        while True:
            t = self.token
            op = t.value
            if t.type in ('TK_OP', 'TK_CHAR', 'TK_KEYWORD') and op in PRECEDENCE:
                prec = PRECEDENCE[op]
                if prec < min_prec:
                    break
                self.advance()
                # Right associative operators: ^ and ..
                next_min_prec = prec if op in ('^', '..') else prec + 1
                right = self.parse_expr(next_min_prec)
                left = BinaryOp(op, left, right)
            else:
                break
        return left

    def parse_primary_expr(self):
        t = self.token
        if t.type == 'TK_KEYWORD':
            if t.value == 'nil': self.advance(); expr = NilLiteral()
            elif t.value == 'true': self.advance(); expr = BooleanLiteral(True)
            elif t.value == 'false': self.advance(); expr = BooleanLiteral(False)
            elif t.value == 'function':
                self.advance()
                params, is_vararg, body = self.parse_func_body()
                expr = FunctionDef(params, is_vararg, body)
            else:
                self.error(f"unexpected keyword '{t.value}'")
        elif t.type == 'TK_NUMBER':
            self.advance()
            expr = NumberLiteral(t.value)
        elif t.type == 'TK_STRING':
            self.advance()
            expr = StringLiteral(t.value)
        elif t.type == 'TK_OP' and t.value == '...':
            self.advance()
            expr = VarargLiteral()
        elif t.type == 'TK_CHAR' and t.value == '{':
            expr = self.parse_table_constructor()
        elif t.type == 'TK_NAME':
            self.advance()
            expr = VarRef(t.value)
        elif t.type == 'TK_CHAR' and t.value == '(':
            self.advance()
            expr = self.parse_expr()
            self.expect('TK_CHAR', ')')
        else:
            self.error(f"unexpected symbol near '{t.value or t.type}'")

        # Suffixed operations: index, field, call, method call
        while True:
            if self.match('TK_CHAR', '['):
                key = self.parse_expr()
                self.expect('TK_CHAR', ']')
                expr = IndexAccess(expr, key)
            elif self.match('TK_CHAR', '.'):
                field = self.expect('TK_NAME')
                expr = FieldAccess(expr, field)
            elif self.match('TK_CHAR', ':'):
                method = self.expect('TK_NAME')
                args = self.parse_args()
                expr = MethodCall(expr, method, args)
            elif self.token.type == 'TK_STRING' or (self.token.type == 'TK_CHAR' and self.token.value in ('(', '{')):
                args = self.parse_args()
                expr = FuncCall(expr, args)
            else:
                break
        return expr

    def parse_args(self):
        if self.match('TK_CHAR', '('):
            args = []
            if not self.match('TK_CHAR', ')'):
                args = self.parse_explist()
                self.expect('TK_CHAR', ')')
            return args
        elif self.token.type == 'TK_STRING':
            s = self.token.value
            self.advance()
            return [StringLiteral(s)]
        elif self.token.type == 'TK_CHAR' and self.token.value == '{':
            t = self.parse_table_constructor()
            return [t]
        else:
            self.error("unexpected args")

    def parse_table_constructor(self):
        self.expect('TK_CHAR', '{')
        entries = [] # list of (key_expr, val_expr)
        while not self.match('TK_CHAR', '}'):
            if self.match('TK_CHAR', '['):
                k = self.parse_expr()
                self.expect('TK_CHAR', ']')
                self.expect('TK_CHAR', '=')
                v = self.parse_expr()
                entries.append((k, v))
            elif self.token.type == 'TK_NAME' and self.lexer.peek() == '=':
                k = StringLiteral(self.token.value)
                self.advance() # name
                self.advance() # '='
                v = self.parse_expr()
                entries.append((k, v))
            else:
                v = self.parse_expr()
                entries.append((None, v))
            if not (self.match('TK_CHAR', ',') or self.match('TK_CHAR', ';')):
                if self.token.type == 'TK_CHAR' and self.token.value == '}':
                    pass
                else:
                    break
        return TableConstructor(entries)
