import sys
import math
import time
import os
import re
import struct

class LuaMultiReturn(tuple): pass

class LuaError(Exception):
    def __init__(self, msg, level=1):
        super().__init__(msg)
        self.msg = msg
        self.level = level

class ReturnSignal(Exception):
    def __init__(self, values): self.values = values

class BreakSignal(Exception): pass

class GotoSignal(Exception):
    def __init__(self, label): self.label = label

class LuaTable:
    def __init__(self, array=None, dict_=None):
        self.array = list(array) if array else []
        self.dict = dict(dict_) if dict_ else {}
        self.metatable = None

    def rawget(self, k):
        if isinstance(k, int) and k >= 1 and k <= len(self.array):
            v = self.array[k - 1]
            return v if v is not None else None
        return self.dict.get(k, None)

    def rawset(self, k, v):
        if isinstance(k, int) and k >= 1:
            if k <= len(self.array):
                self.array[k - 1] = v
                return
            elif k == len(self.array) + 1:
                self.array.append(v)
                return
        if v is None:
            self.dict.pop(k, None)
        else:
            self.dict[k] = v

    def len(self):
        for i in range(len(self.array), 0, -1):
            if self.array[i - 1] is not None:
                return i
        return 0

    def keys(self):
        ks = []
        for i in range(1, len(self.array) + 1):
            if self.array[i - 1] is not None:
                ks.append(i)
        for k in self.dict.keys():
            if k not in ks:
                ks.append(k)
        return ks

    def __repr__(self):
        return f"table: 0x{id(self):x}"

class LuaUserdata:
    def __init__(self, name, data=None):
        self.name = name
        self.data = data
        self.metatable = None
    def __repr__(self):
        return f"userdata: 0x{id(self):x}"

class LuaThread:
    def __init__(self, func):
        self.func = func
        self.status = 'suspended' # suspended, running, normal, dead
        self.gen = None
    def __repr__(self):
        return f"thread: 0x{id(self):x}"

class LuaFunction:
    def __init__(self, py_func, name=None):
        self.py_func = py_func
        self.name = name
    def __call__(self, *args, **kwargs):
        return self.py_func(*args, **kwargs)
    def __repr__(self):
        return f"function: 0x{id(self):x}"

def lua_is_truthy(v):
    return v is not None and v is not False

def lua_type(v):
    if v is None: return "nil"
    if isinstance(v, bool): return "boolean"
    if isinstance(v, (int, float)): return "number"
    if isinstance(v, str): return "string"
    if isinstance(v, LuaTable): return "table"
    if isinstance(v, (LuaFunction, type(lambda: None))): return "function"
    if isinstance(v, LuaThread): return "thread"
    if isinstance(v, LuaUserdata): return "userdata"
    return "userdata"

def lua_tostring(v):
    if v is None: return "nil"
    if isinstance(v, bool): return "true" if v else "false"
    if isinstance(v, float):
        if v.is_integer():
            return f"{v}"
        return str(v)
    if isinstance(v, int):
        return str(v)
    if isinstance(v, str):
        return v
    if isinstance(v, LuaTable):
        if v.metatable:
            mt_ts = v.metatable.rawget('__tostring')
            if mt_ts:
                res = lua_call(mt_ts, v)
                return lua_tostring(res)
        return f"table: 0x{id(v):x}"
    if isinstance(v, (LuaFunction, type(lambda: None))):
        return f"function: 0x{id(v):x}"
    if isinstance(v, LuaThread):
        return f"thread: 0x{id(v):x}"
    if isinstance(v, LuaUserdata):
        return f"userdata: 0x{id(v):x}"
    return str(v)

def lua_tonumber(v, base=10):
    if isinstance(v, (int, float)): return v
    if isinstance(v, str):
        s = v.strip()
        try:
            if base == 10:
                if s.startswith(('0x', '0X')):
                    return int(s, 16)
                if '.' in s or 'e' in s or 'E' in s:
                    return float(s)
                return int(s)
            else:
                return int(s, base)
        except ValueError:
            return None
    return None

def lua_gettable(t, k):
    if isinstance(t, LuaTable):
        val = t.rawget(k)
        if val is not None:
            return val
        if t.metatable:
            idx = t.metatable.rawget('__index')
            if idx is not None:
                if isinstance(idx, LuaTable):
                    return lua_gettable(idx, k)
                elif callable(idx) or isinstance(idx, LuaFunction):
                    return lua_call(idx, t, k)
