            return na + nb
        return float(na) + float(nb)
    # Metamethod
    mm = _get_bin_mm(a, b, '__add')
    if mm: return lua_call(mm, a, b)
    raise LuaError(f"attempt to perform arithmetic on a {lua_type(a if na is None else b)} value")

